/** The bridge the runtime speaks through: generic protocol in, typed store out. */
class PaymentsStoreResolver(
    private val store: PaymentsStore,
    model: Model,
) : StateResolver {
    private val questions = PaymentsStoreQuestions(model)

    override fun fetchByKey(shape: String, key: StoreKey): Row? = when (shape) {
        "Contact" -> store.contact(key)?.toRow()
        "Card" -> store.card(key)?.toRow()
        "Customer" -> store.customer(key)?.toRow()
        "CardUpdate" -> store.cardUpdate(key)?.toRow()
        "Order" -> store.order(key)?.toRow()
        "ChargeAttempt" -> store.chargeAttempt(key)?.toRow()
        "ChargeResponse" -> store.chargeResponse(key)?.toRow()
        "AttemptTimeout" -> store.attemptTimeout(key)?.toRow()
        "StockReservation" -> store.stockReservation(key)?.toRow()
        "ReservationRelease" -> store.reservationRelease(key)?.toRow()
        "Receipt" -> store.receipt(key)?.toRow()
        "Shipment" -> store.shipment(key)?.toRow()
        "ChangeShippingAddress" -> store.changeShippingAddress(key)?.toRow()
        "AddressChangeApplication" -> store.addressChangeApplication(key)?.toRow()
        "AddressChangeRefusal" -> store.addressChangeRefusal(key)?.toRow()
        "Refund" -> store.refund(key)?.toRow()
        "SettlementReversal" -> store.settlementReversal(key)?.toRow()
        "ManualCharge" -> store.manualCharge(key)?.toRow()
        "ExtensionRequest" -> store.extensionRequest(key)?.toRow()
        "PaymentExtension" -> store.paymentExtension(key)?.toRow()
        "PaymentReminder" -> store.paymentReminder(key)?.toRow()
        "DunningFlag" -> store.dunningFlag(key)?.toRow()
        "DunningResolution" -> store.dunningResolution(key)?.toRow()
        else -> null
    }

    override fun fetchAll(shape: String): List<Row> = when (shape) {
        "Contact" -> store.allContacts().map { it.toRow() }
        "Card" -> store.allCards().map { it.toRow() }
        "Customer" -> store.allCustomers().map { it.toRow() }
        "CardUpdate" -> store.allCardUpdates().map { it.toRow() }
        "Order" -> store.allOrders().map { it.toRow() }
        "ChargeAttempt" -> store.allChargeAttempts().map { it.toRow() }
        "ChargeResponse" -> store.allChargeResponses().map { it.toRow() }
        "AttemptTimeout" -> store.allAttemptTimeouts().map { it.toRow() }
        "StockReservation" -> store.allStockReservations().map { it.toRow() }
        "ReservationRelease" -> store.allReservationReleases().map { it.toRow() }
        "Receipt" -> store.allReceipts().map { it.toRow() }
        "Shipment" -> store.allShipments().map { it.toRow() }
        "ChangeShippingAddress" -> store.allChangeShippingAddresss().map { it.toRow() }
        "AddressChangeApplication" -> store.allAddressChangeApplications().map { it.toRow() }
        "AddressChangeRefusal" -> store.allAddressChangeRefusals().map { it.toRow() }
        "Refund" -> store.allRefunds().map { it.toRow() }
        "SettlementReversal" -> store.allSettlementReversals().map { it.toRow() }
        "ManualCharge" -> store.allManualCharges().map { it.toRow() }
        "ExtensionRequest" -> store.allExtensionRequests().map { it.toRow() }
        "PaymentExtension" -> store.allPaymentExtensions().map { it.toRow() }
        "PaymentReminder" -> store.allPaymentReminders().map { it.toRow() }
        "DunningFlag" -> store.allDunningFlags().map { it.toRow() }
        "DunningResolution" -> store.allDunningResolutions().map { it.toRow() }
        else -> emptyList()
    }

    override fun fetchReferencing(shape: String, field: String, target: Ref.Persisted): List<Row> = when {
        shape == "Card" && field == "billingContact" -> store.cardsByBillingContact(target).map { it.toRow() }
        shape == "Customer" && field == "card" -> store.customersByCard(target).map { it.toRow() }
        shape == "CardUpdate" && field == "customer" -> store.cardUpdatesByCustomer(target).map { it.toRow() }
        shape == "CardUpdate" && field == "card" -> store.cardUpdatesByCard(target).map { it.toRow() }
        shape == "Order" && field == "customer" -> store.ordersByCustomer(target).map { it.toRow() }
        shape == "ChargeAttempt" && field == "order" -> store.chargeAttemptsByOrder(target).map { it.toRow() }
        shape == "ChargeResponse" && field == "attempt" -> store.chargeResponsesByAttempt(target).map { it.toRow() }
        shape == "AttemptTimeout" && field == "attempt" -> store.attemptTimeoutsByAttempt(target).map { it.toRow() }
        shape == "StockReservation" && field == "order" -> store.stockReservationsByOrder(target).map { it.toRow() }
        shape == "ReservationRelease" && field == "reservation" -> store.reservationReleasesByReservation(target).map { it.toRow() }
        shape == "Receipt" && field == "attempt" -> store.receiptsByAttempt(target).map { it.toRow() }
        shape == "Shipment" && field == "order" -> store.shipmentsByOrder(target).map { it.toRow() }
        shape == "ChangeShippingAddress" && field == "order" -> store.changeShippingAddresssByOrder(target).map { it.toRow() }
        shape == "AddressChangeApplication" && field == "change" -> store.addressChangeApplicationsByChange(target).map { it.toRow() }
        shape == "AddressChangeRefusal" && field == "change" -> store.addressChangeRefusalsByChange(target).map { it.toRow() }
        shape == "Refund" && field == "order" -> store.refundsByOrder(target).map { it.toRow() }
        shape == "SettlementReversal" && field == "order" -> store.settlementReversalsByOrder(target).map { it.toRow() }
        shape == "ManualCharge" && field == "order" -> store.manualChargesByOrder(target).map { it.toRow() }
        shape == "ExtensionRequest" && field == "order" -> store.extensionRequestsByOrder(target).map { it.toRow() }
        shape == "PaymentExtension" && field == "order" -> store.paymentExtensionsByOrder(target).map { it.toRow() }
        shape == "PaymentReminder" && field == "order" -> store.paymentRemindersByOrder(target).map { it.toRow() }
        shape == "DunningFlag" && field == "order" -> store.dunningFlagsByOrder(target).map { it.toRow() }
        shape == "DunningResolution" && field == "flag" -> store.dunningResolutionsByFlag(target).map { it.toRow() }
        else -> emptyList()
    }

    override fun fetchCandidates(shape: String, filter: QF): List<Row> {
        if (shape == "Order")
            questions.neverChargedCandidates.match(filter)?.let { h -> return store.neverChargedCandidates().map { it.toRow() } }
        if (shape == "Order")
            questions.refundedOrderCandidates.match(filter)?.let { h -> return store.refundedOrderCandidates().map { it.toRow() } }
        if (shape == "Order")
            questions.chargeableOrderCandidates.match(filter)?.let { h -> return store.chargeableOrderCandidates(h.date(0)).map { it.toRow() } }
        if (shape == "ChargeAttempt")
            questions.pendingAttemptCandidates.match(filter)?.let { h -> return store.pendingAttemptCandidates().map { it.toRow() } }
        if (shape == "ChargeAttempt")
            questions.completedAttemptCandidates.match(filter)?.let { h -> return store.completedAttemptCandidates().map { it.toRow() } }
        if (shape == "ChargeAttempt")
            questions.timedOutAttemptCandidates.match(filter)?.let { h -> return store.timedOutAttemptCandidates().map { it.toRow() } }
        if (shape == "StockReservation")
            questions.activeReservationCandidates.match(filter)?.let { h -> return store.activeReservationCandidates().map { it.toRow() } }
        if (shape == "Order")
            questions.retryableOrderCandidates.match(filter)?.let { h -> return store.retryableOrderCandidates().map { it.toRow() } }
        if (shape == "ChargeAttempt")
            questions.stalePendingAttemptCandidates.match(filter)?.let { h -> return store.stalePendingAttemptCandidates(h.instant(0)).map { it.toRow() } }
        if (shape == "Order")
            questions.unshippedOrderCandidates.match(filter)?.let { h -> return store.unshippedOrderCandidates().map { it.toRow() } }
        if (shape == "ChangeShippingAddress")
            questions.unhandledAddressChangeCandidates.match(filter)?.let { h -> return store.unhandledAddressChangeCandidates().map { it.toRow() } }
        if (shape == "ChangeShippingAddress")
            questions.refusedAddressChangeCandidates.match(filter)?.let { h -> return store.refusedAddressChangeCandidates().map { it.toRow() } }
        if (shape == "Order")
            questions.overdueOrderCandidates.match(filter)?.let { h -> return store.overdueOrderCandidates(h.date(0)).map { it.toRow() } }
        if (shape == "DunningFlag")
            questions.openDunningFlagCandidates.match(filter)?.let { h -> return store.openDunningFlagCandidates().map { it.toRow() } }
        if (shape == "Order")
            questions.reserveStockCandidates.match(filter)?.let { h -> return store.reserveStockCandidates().map { it.toRow() } }
        if (shape == "Order")
            questions.requestInitialChargeCandidates.match(filter)?.let { h -> return store.requestInitialChargeCandidates(h.date(0)).map { it.toRow() } }
        if (shape == "Order")
            questions.releaseStockOnExhaustionCandidates.match(filter)?.let { h -> return store.releaseStockOnExhaustionCandidates().map { it.toRow() } }
        if (shape == "Order")
            questions.remindPaymentCandidates.match(filter)?.let { h -> return store.remindPaymentCandidates(h.date(0), h.date(1)).map { it.toRow() } }
        if (shape == "Order")
            questions.openDunningEpisodeCandidates.match(filter)?.let { h -> return store.openDunningEpisodeCandidates(h.date(0)).map { it.toRow() } }
        return fetchAll(shape) // unrecognized filters fall back to the scan floor
    }

    override fun fetchCaptures(instance: Ref.Persisted, refinement: String): Map<String, Any?>? = when (refinement) {
        else -> null
    }
}

private fun List<QConst>.date(i: Int): LocalDate = (this[i] as QConst.QDate).v
private fun List<QConst>.instant(i: Int): Instant = (this[i] as QConst.QDateTime).v

// ── row mappers: the generic wire format <-> the typed rows ──

fun Row.toContactRow(): ContactRow = ContactRow(
    key = key,
    name = fields["name"] as String,
    email = fields["email"] as String,
)

fun ContactRow.toRow(): Row = Row("Contact", key, buildMap {
    put("name", name)
    put("email", email)
})

fun Row.toCardRow(): CardRow = CardRow(
    key = key,
    number = fields["number"] as String,
    expiresOn = fields["expiresOn"] as LocalDate,
    billingContact = fields["billingContact"] as Ref.Persisted?,
)

fun CardRow.toRow(): Row = Row("Card", key, buildMap {
    put("number", number)
    put("expiresOn", expiresOn)
    billingContact?.let { put("billingContact", it) }
})

fun Row.toCustomerRow(): CustomerRow = CustomerRow(
    key = key,
    name = fields["name"] as String,
    card = fields["card"] as Ref.Persisted?,
)

fun CustomerRow.toRow(): Row = Row("Customer", key, buildMap {
    put("name", name)
    card?.let { put("card", it) }
})

